\label{conj:emc}
  Let $n,k,s$ be positive integers with $n\ge k(s+1)$.
  If $\mathcal F\subseteq\binom{[n]}k$ and $\nu(\mathcal F)\le s$, then $|\mathcal F|\le\max\{C_k(s),M_k(n,s)\}$.

\label{lem:crossing-parameters}
    For every integer $k\ge2$, the equation $g_k(c)=1$ has a unique solution $c=c_k$ in $[0,\infty)$, and ${\beta_k}$ is the unique solution of $1-(1-x)^k=(kx)^k$ in $(0,1/k]$.
    Moreover, $c_2=1/2$ and $0<c_k<1/2$ for $k\ge3$.

\label{fact:comparison-arrays}
  Let $k\ge2$, and use the comparison values $e_j^{(s)},f_j^{(s)}$ and their interpolants $e_j^*,f_j^*$ defined above.
  \begin{enumerate}[label=\textup{(\roman*)},leftmargin=*,itemsep=0pt]
    \item\label{it:comparison-node-arrays} For $1\le s\le k$ and $1\le j\le k$,
    \[
      (e_j^{(s)},f_j^{(s)})=
      \begin{cases}
        (0,0),                                                & j\le k-s, \\
        \bigl(j-k+s(1-1/s)^{j-k+s},\,1-(1-1/s)^{j-k+s}\bigr), & j>k-s.
      \end{cases}
    \]
    Moreover, $e_1^{(s)}=0$, $e_{j+1}^{(s)}=e_j^{(s)}+f_j^{(s)}$ for $1\le j<k$, and $e_k^{(s)}=\sum_{j<k}f_j^{(s)}=W_s$.
    \item\label{it:comparison-interpolated-budget} For $0\le w\le W_k$, we have
    \[
      \begin{aligned}
        e_1^*(w) & =0,\text{ }e_{j+1}^*(w)=e_j^*(w)+f_j^*(w)\quad(1\le j<k), \\
        e_k^*(w) & =w=\sum_{j<k}f_j^*(w).
      \end{aligned}
    \]
  \end{enumerate}

\label{cor:small-omega}
    Let $k\ge6$ and $x=\beta_k$, and let $\mathsf P$ maximize $F_k$ among nonnegative Borel laws of mean at most $x$.
    If $0<w<W_k$, then the conditional decomposition with $\varepsilon=1/16$ and $\zeta=17/20$ satisfies $0<\eta<a/10<1/10$.

\label{fact:construction-densities}
  For fixed $k\ge3$ and positive integers $n,s$ with $n\ge k(s+1)$, the following estimates hold uniformly.
  \begin{enumerate}[label=\textup{(\roman*)},leftmargin=*,itemsep=0pt]
    \item\label{it:construction-cover-density} We have $M_k(n,s)/\binom nk=1-(1-s/n)^k+O_k(n^{-1})$.
    \item\label{it:construction-clique-density} We have $C_k(s)/\binom nk=(ks/n)^k+O_k(n^{-1})$.
  \end{enumerate}

\label{lem:matching-sequence}
  Fix $k\ge3$.
  Let $(n_i,s_i)$ be integer pairs with $s_i\to\infty$, $n_i\ge k(s_i+1)$, and $n_i/s_i\to R<\infty$ as $i\to\infty$.
  Suppose $\mathcal F_i\subseteq\binom{[n_i]}k$ satisfies $\nu(\mathcal F_i)\le s_i$ and $|\mathcal F_i|\ge D_k(n_i,s_i)-o(n_i^k)$.
  For each $i$, define its distances from the two constructions by
  \[
    d_C(\mathcal F_i)=\min_{\substack{Q\subseteq[n_i]\\|Q|=ks_i+k-1}}
    \left|\mathcal F_i\triangle\binom Qk\right|
    \text{ and }
    d_B(\mathcal F_i)=\min_{\substack{S\subseteq[n_i]\\|S|=s_i}}
    \left|\mathcal F_i\triangle\mathcal A(S)\right|.
  \]
  Then the following asymptotic conclusions hold as $i\to\infty$ along the original sequence.
  \begin{enumerate}[label=\textup{(\roman*)},leftmargin=*,itemsep=0pt]
    \item\label{it:matching-sequence-dichotomy} We have $\min\{d_C(\mathcal F_i),d_B(\mathcal F_i)\}=o(n_i^k)$.
    \item\label{it:matching-sequence-clique}\label{it:matching-sequence-cover}
    If $k\le R<\rho_k$, then $d_C(\mathcal F_i)=o(n_i^k)$.
    If $R>\rho_k$, then $d_B(\mathcal F_i)=o(n_i^k)$.
    At $R=\rho_k$, the approximating construction in~\textup{(i)} may be a clique family for some indices and a cover family for others.
  \end{enumerate}
